    # step 1: add small multiplicative noise (relative jitter ~1e-3)
    noise = torch.randn_like(x) * module.noise_scale * x.abs().clamp_min(1e-8)
    x_noisy = x + noise
    # step 2: cast to the target dtype (type_as semantics)
    return x_noisy.to(other.dtype)

def forward(module, x, other):
    # step 1: quantize to 8-bit per-tensor symmetric
    scale = module.scale if hasattr(module, "scale") else x.abs().max() / 127.0
    q = torch.clamp(torch.round(x / scale), -127, 127)
    # step 2: dequantize and cast to the target dtype (type_as semantics)
    return (q * scale).to(other.dtype)

