def forward(module, x):
    import torch
    # locate the constant mask attribute on the module
    M = None
    for name in dir(module):
        if name.startswith('_'):
            continue
        v = getattr(module, name)
        if torch.is_tensor(v) and v.ndim == 2 and v.shape == (256, 256):
            M = v
            break
    assert M is not None, 'no 256x256 constant found'
    x2 = x.reshape(1, 256)
    out = torch.matmul(x2, M.t())
    return out.reshape(1, 256)

